INSERT INTO generated_content VALUES(1,48,NULL,'email',NULL,unistr('Subject: Exploring Financing Opportunities for Gantry\u000a\u000aHi Andy,\u000a\u000aI’m Chris Rabenold from Harvest Small Business Finance. We specialize in SBA 504 loans, offering 90% financing for owner-occupied commercial real estate. This could be a strategic move for Gantry to build equity instead of paying rent. I''d welcome the chance to discuss how we can support your growth objectives.\u000a\u000aBest regards,\u000a\u000aChris Rabenold  \u000aSenior Vice President, Business Development  \u000aHarvest Small Business Finance  '),'gpt-4o','{"relationship_level": "cold", "years_known": 0, "last_interaction": "", "common_ground": null, "referral_potential": "", "personal_notes": "", "professional_notes": "we are friendly and like talking to each other"}',NULL,'draft','2025-11-25 04:34:24',NULL);
INSERT INTO generated_content VALUES(2,48,NULL,'email',NULL,unistr('Subject: Exploring Financing Options for Gantry''s Growth\u000a\u000aHi Andy,\u000a\u000aI''m Chris Rabenold from Harvest Small Business Finance. We specialize in SBA 504 loans, offering 90% financing for owner-occupied commercial real estate. Our solutions help businesses like Gantry build equity rather than rent. If you''re exploring expansion or relocation, I''d welcome the opportunity to discuss how we can support Gantry''s growth.\u000a\u000aBest,\u000aChris Rabenold\u000aSenior Vice President, Business Development\u000aHarvest Small Business Finance'),'gpt-4o','{"relationship_level": "cold", "years_known": 0, "last_interaction": "", "common_ground": null, "referral_potential": "", "personal_notes": "", "professional_notes": "we are friendly and like talking to each other"}',NULL,'draft','2025-11-25 04:34:27',NULL);
INSERT INTO generated_content VALUES(3,48,NULL,'email',NULL,unistr('Subject: Exploring Financing Opportunities for Gantry\u000a\u000aHi Andy,\u000a\u000aI''m Chris Rabenold from Harvest Small Business Finance. We specialize in SBA 504 loans, offering 90% financing for owner-occupied commercial real estate. Our solutions could support Gantry in building equity and enhancing operational efficiency. I’d love to discuss how we can assist in your growth strategy. \u000a\u000aBest regards,\u000a\u000aChris Rabenold\u000aSenior Vice President, Business Development\u000aHarvest Small Business Finance'),'gpt-4o','{"relationship_level": "cold", "years_known": 0, "last_interaction": "", "common_ground": null, "referral_potential": "", "personal_notes": "", "professional_notes": "we are friendly and like talking to each other"}',NULL,'draft','2025-11-25 04:34:40',NULL);
INSERT INTO generated_content VALUES(4,48,NULL,'email',NULL,unistr('Subject: Unlocking CRE Opportunities with SBA 504 Loans\u000a\u000aHi Andy,\u000a\u000aI''m Chris Rabenold from Harvest Small Business Finance. We specialize in SBA 504 loans, offering 90% financing with just 10% down for owner-occupied commercial real estate. This could help your clients build equity rather than pay rent. I''d love to discuss how this can benefit Gantry''s ventures. Please let me know a convenient time for a brief call.\u000a\u000aBest,\u000aChris Rabenold  \u000aSenior Vice President, Business Development'),'gpt-4o','{"relationship_level": "cold", "years_known": 0, "last_interaction": "", "common_ground": null, "referral_potential": "", "personal_notes": "", "professional_notes": "we are friendly and like talking to each other"}',NULL,'draft','2025-11-25 04:34:54',NULL);
